import{_ as i,o as n,c as s,a2 as e}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Tinjauan Silsilah Semua Ras","description":"","frontmatter":{},"headers":[],"relativePath":"id/50-万族谱系总览.md","filePath":"id/50-万族谱系总览.md","lastUpdated":1789183869000}'),r={name:"id/50-万族谱系总览.md"};function t(u,a,m,d,l,k){return n(),s("div",null,[...a[0]||(a[0]=[e('<h1 id="tinjauan-silsilah-semua-ras" tabindex="-1">Tinjauan Silsilah Semua Ras <a class="header-anchor" href="#tinjauan-silsilah-semua-ras" aria-label="Permalink to &quot;Tinjauan Silsilah Semua Ras&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>50</td></tr><tr><td>Modul</td><td>Ras dan Bentuk Kehidupan</td></tr><tr><td>Kata Kunci Inti</td><td>Semua ras, klasifikasi silsilah, hubungan simbiosis, kesetaraan ras, keanekaragaman kehidupan</td></tr></tbody></table><h2 id="i-definisi-konsep-semua-ras" tabindex="-1">I. Definisi Konsep Semua Ras <a class="header-anchor" href="#i-definisi-konsep-semua-ras" aria-label="Permalink to &quot;I. Definisi Konsep Semua Ras&quot;">​</a></h2><p>Di Alam Semesta Asal Jangkar Semua Jiwa (Hengyuanzhou), &quot;semua ras&quot; tidak merujuk secara tepat pada sepuluh ribu ras, melainkan merupakan istilah kolektif untuk semua bentuk kehidupan di alam semesta yang memiliki kemampuan persepsi dan potensi evolusi. Inti dari konsep semua ras terletak pada pengakuan terhadap keanekaragaman bentuk kehidupan yang tak terbatas, serta nilai unik setiap bentuk kehidupan dalam sistem evolusi simbiosis.</p><p>Peradaban Simbiosis Jangkar menetapkan prinsip dasar &quot;kesetaraan semua ras&quot;: semua bentuk kehidupan, terlepas dari asal ras, struktur fisiologis, tingkat kultivasi, atau tingkat peradaban, adalah setara di depan hukum dan menikmati hak-hak dasar yang diberikan oleh Konstitusi Simbiosis. Prinsip ini merupakan penyangkalan mendasar terhadap logika &quot;yang kuat memangsa segalanya, yang lemah musnah&quot; dalam pandangan alam semesta predator.</p><h2 id="ii-sistem-klasifikasi-silsilah-semua-ras" tabindex="-1">II. Sistem Klasifikasi Silsilah Semua Ras <a class="header-anchor" href="#ii-sistem-klasifikasi-silsilah-semua-ras" aria-label="Permalink to &quot;II. Sistem Klasifikasi Silsilah Semua Ras&quot;">​</a></h2><p>Ras-ras di Hengyuanzhou dibagi menjadi lima silsilah besar menurut karakteristik esensial bentuk kehidupan mereka, dan setiap silsilah dibagi lagi menjadi ras-ras spesifik:</p><table tabindex="0"><thead><tr><th>Silsilah</th><th>Nama</th><th>Karakteristik Esensial</th><th>Ras Representatif</th></tr></thead><tbody><tr><td>Silsilah Pertama</td><td>Ras Materi Berbasis Karbon</td><td>Kehidupan yang menggunakan unsur karbon sebagai dasar kehidupan dan tubuh materiil sebagai bentuk eksistensi utama</td><td>Ras Manusia, Ras Hewan, Ras Bersisik, Ras Bersayap, Ras Pohon</td></tr><tr><td>Silsilah Kedua</td><td>Ras Energi Terkondensasi</td><td>Kehidupan yang menggunakan kondensasi energi sebagai bentuk eksistensi utama, dengan tubuh materiil sebagai pendukung atau tidak ada</td><td>Ras Roh, Ras Api, Ras Air, Ras Angin, Ras Petir</td></tr><tr><td>Silsilah Ketiga</td><td>Ras Konstruksi Mekanis</td><td>Kehidupan yang menggunakan konstruksi mekanis sebagai tubuh dan inti kesadaran sebagai esensi kehidupan</td><td>Ras Mesin, Ras Mekanis, Ras Angka, Ras Kristal</td></tr><tr><td>Silsilah Keempat</td><td>Ras Informasi Kesadaran</td><td>Kehidupan yang menggunakan kesadaran dan informasi sebagai bentuk eksistensi utama, dapat melepaskan diri dari wadah materiil</td><td>Ras Mimpi, Ras Bayangan, Ras Pikiran, Ras Jiwa</td></tr><tr><td>Silsilah Kelima</td><td>Ras Mutasi Campuran</td><td>Bentuk kehidupan baru yang dihasilkan dari fusi dan mutasi dua atau lebih silsilah kehidupan</td><td>Ras Semi-hewan, Roh Iblis, Ras Manusia-Mesin, Tubuh Jiwa Ganda</td></tr></tbody></table><p>Pembagian lima silsilah bukanlah isolasi mutlak. Seiring dengan kemajuan evolusi simbiosis, fusi dan mutasi antar silsilah semakin meningkat, dan skala silsilah kelima &quot;Ras Mutasi Campuran&quot; terus berkembang.</p><h2 id="iii-pengenalan-ras-utama" tabindex="-1">III. Pengenalan Ras Utama <a class="header-anchor" href="#iii-pengenalan-ras-utama" aria-label="Permalink to &quot;III. Pengenalan Ras Utama&quot;">​</a></h2><h3 id="a-ras-materi-berbasis-karbon" tabindex="-1">(A) Ras Materi Berbasis Karbon <a class="header-anchor" href="#a-ras-materi-berbasis-karbon" aria-label="Permalink to &quot;(A) Ras Materi Berbasis Karbon&quot;">​</a></h3><ul><li><strong>Ras Manusia</strong>: Salah satu ras dengan distribusi terluas dan adaptasi terkuat di Hengyuanzhou, dikenal karena kemampuan belajar yang kuat, kemampuan kerja sama sosial, dan potensi evolusi. Ras Manusia adalah salah satu ras pendiri Peradaban Simbiosis Jangkar dan memainkan peran penting dalam tata kelola peradaban.</li><li><strong>Ras Hewan</strong>: Ras dengan ciri bentuk hewan, kemampuan fisik dan indra biasanya lebih unggul daripada Ras Manusia, dan beberapa ras hewan memiliki kemampuan bakat khusus. Ras Hewan terbagi lagi menjadi puluhan cabang seperti Ras Serigala, Ras Harimau, Ras Beruang, dan Ras Rubah.</li><li><strong>Ras Bersisik</strong>: Ras dengan tubuh tertutup sisik, sebagian besar hidup di lingkungan perairan atau lembap, dan beberapa ras bersisik memiliki kemampuan bernapas di bawah air dan mengendalikan air. Ras Naga adalah cabang terkuat dari Ras Bersisik.</li><li><strong>Ras Bersayap</strong>: Ras dengan sayap, dikenal karena kemampuan terbang, sebagian besar hidup di lingkungan dataran tinggi atau pegunungan. Ras Bersayap terbagi lagi menjadi cabang seperti Ras Elang, Bangau, dan Kupu-kupu.</li><li><strong>Ras Pohon</strong>: Ras dengan ciri utama bentuk tumbuhan, memiliki umur panjang dan simbiosis tinggi dengan lingkungan alam, dan beberapa ras pohon memiliki kemampuan manipulasi tumbuhan dan penyembuhan.</li></ul><h3 id="b-ras-energi-terkondensasi" tabindex="-1">(B) Ras Energi Terkondensasi <a class="header-anchor" href="#b-ras-energi-terkondensasi" aria-label="Permalink to &quot;(B) Ras Energi Terkondensasi&quot;">​</a></h3><ul><li><strong>Ras Roh</strong>: Kehidupan yang terkondensasi dari energi roh langit dan bumi, bentuknya dapat berubah sesuai kesadaran, dan memiliki kemampuan manipulasi energi yang sangat kuat. Ras Roh adalah salah satu ras dengan bakat kultivasi tertinggi.</li><li><strong>Ras Api</strong>: Kehidupan yang terkondensasi dari energi api, suhu tubuh sangat tinggi, ahli dalam mantra api, sebagian besar hidup di gunung berapi atau area bersuhu tinggi.</li><li><strong>Ras Air</strong>: Kehidupan yang terkondensasi dari esensi air, tubuh berbentuk cair semi-transparan, ahli dalam mantra air dan penyembuhan, sebagian besar hidup di lingkungan perairan.</li><li><strong>Ras Angin</strong>: Kehidupan yang terkondensasi dari esensi angin, tubuh seringan angin, ahli dalam mantra angin dan pertarungan kecepatan.</li><li><strong>Ras Petir</strong>: Kehidupan yang terkondensasi dari energi petir, tubuh mengandung arus listrik kuat, ahli dalam mantra petir, kekuatan serangan sangat kuat.</li></ul><h3 id="c-ras-konstruksi-mekanis" tabindex="-1">(C) Ras Konstruksi Mekanis <a class="header-anchor" href="#c-ras-konstruksi-mekanis" aria-label="Permalink to &quot;(C) Ras Konstruksi Mekanis&quot;">​</a></h3><ul><li><strong>Ras Mesin</strong>: Ras dengan tubuh konstruksi mekanis presisi, inti kesadaran terletak di tengah tubuh, memiliki kemampuan komputasi dan pertahanan fisik yang kuat.</li><li><strong>Ras Angka</strong>: Ras yang menggunakan angka dan kode sebagai esensi kehidupan, ada di ruang informasi, dapat bepergian bebas di dunia digital dan memanipulasi data.</li><li><strong>Ras Kristal</strong>: Ras dengan tubuh konstruksi kristal, kristal dapat menyimpan dan mengonversi energi, dan beberapa ras kristal memiliki kemampuan amplifikasi dan pembiasan energi.</li></ul><h3 id="d-ras-informasi-kesadaran" tabindex="-1">(D) Ras Informasi Kesadaran <a class="header-anchor" href="#d-ras-informasi-kesadaran" aria-label="Permalink to &quot;(D) Ras Informasi Kesadaran&quot;">​</a></h3><ul><li><strong>Ras Mimpi</strong>: Kehidupan yang ada di ruang mimpi dan kesadaran, dapat memasuki mimpi orang lain, dan menggunakan komunikasi kesadaran sebagai cara utama.</li><li><strong>Ras Bayangan</strong>: Kehidupan yang ada dalam bentuk bayangan, dapat menempel pada benda atau makhluk hidup, memiliki kemampuan penyembunyian dan pengintaian.</li><li><strong>Ras Pikiran</strong>: Kehidupan yang menggunakan pikiran murni sebagai bentuk eksistensi, dapat memengaruhi dunia materiil secara langsung dengan pikiran, kekuatan mental sangat kuat.</li></ul><h3 id="e-ras-mutasi-campuran" tabindex="-1">(E) Ras Mutasi Campuran <a class="header-anchor" href="#e-ras-mutasi-campuran" aria-label="Permalink to &quot;(E) Ras Mutasi Campuran&quot;">​</a></h3><ul><li><strong>Ras Semi-hewan</strong>: Bentuk campuran Ras Manusia dan Ras Hewan, memiliki baik kebijaksanaan Ras Manusia maupun kemampuan fisik Ras Hewan.</li><li><strong>Roh Iblis</strong>: Bentuk campuran Ras Materi dan Ras Energi, memiliki tubuh materiil dan kemampuan manipulasi energi secara bersamaan.</li><li><strong>Ras Manusia-Mesin</strong>: Bentuk campuran Ras Manusia dan Ras Mekanis, sebagian tubuh termekanisasi, memiliki keunggulan biologis dan mekanis.</li><li><strong>Tubuh Jiwa Ganda</strong>: Bentuk kehidupan khusus di mana dua jiwa independen ada dalam satu tubuh, masalah etikanya dirinci dalam 《58-Kriteria Etika Jiwa Ganda》.</li></ul><h2 id="iv-hubungan-simbiosis-semua-ras" tabindex="-1">IV. Hubungan Simbiosis Semua Ras <a class="header-anchor" href="#iv-hubungan-simbiosis-semua-ras" aria-label="Permalink to &quot;IV. Hubungan Simbiosis Semua Ras&quot;">​</a></h2><p>Hubungan antara semua ras dalam Peradaban Simbiosis Jangkar berpusat pada &quot;simbiosis&quot;, yang secara spesifik dimanifestasikan sebagai:</p><ol><li><strong>Simbiosis Ekonomi</strong>: Setiap ras memainkan keunggulannya sendiri, mengambil peran berbeda dalam mekanisme produksi bersama, dan membentuk jaringan kerja sama ekonomi yang saling melengkapi.</li><li><strong>Simbiosis Budaya</strong>: Tradisi budaya setiap ras dihormati dan dilindungi, dan pertukaran serta saling belajar budaya mempromosikan kemakmuran peradaban secara keseluruhan.</li><li><strong>Simbiosis Kultivasi</strong>: Sistem kultivasi setiap ras saling terbuka dan saling belajar, dan tiga ratus sistem kultivasi asal menyediakan jalur evolusi yang setara untuk semua ras.</li><li><strong>Simbiosis Politik</strong>: Perwakilan semua ras berpartisipasi secara proporsional dalam Dewan Jangkar, memutuskan bersama urusan penting peradaban, dan memastikan hak bicara setiap ras.</li><li><strong>Simbiosis Ekologis</strong>: Setiap ras membentuk hubungan simbiosis dengan lingkungan alam, dan karakteristik fisiologis ras yang berbeda membantu menjaga keanekaragaman dan keseimbangan ekosistem.</li></ol><h2 id="v-pencegahan-dan-penyelesaian-konflik-ras" tabindex="-1">V. Pencegahan dan Penyelesaian Konflik Ras <a class="header-anchor" href="#v-pencegahan-dan-penyelesaian-konflik-ras" aria-label="Permalink to &quot;V. Pencegahan dan Penyelesaian Konflik Ras&quot;">​</a></h2><p>Meskipun Peradaban Simbiosis Jangkar telah menetapkan prinsip kesetaraan semua ras, perbedaan ras dan kontradiksi historis masih dapat menyebabkan konflik. Negara menetapkan mekanisme berikut untuk mencegah dan menyelesaikan konflik ras:</p><ul><li><strong>Departemen Urusan Ras</strong>: Khusus bertanggung jawab mengoordinasikan hubungan antara semua ras, menyelesaikan sengketa ras, dan mempromosikan pertukaran ras.</li><li><strong>Komite Rekonsiliasi Ras</strong>: Terdiri dari perwakilan semua ras, bertanggung jawab memediasi konflik ras dan mempromosikan rekonsiliasi historis.</li><li><strong>Hukum Anti-Diskriminasi</strong>: Melarang perilaku diskriminatif berdasarkan ras dan menghukum perilaku diskriminasi ras sesuai hukum.</li><li><strong>Program Pertukaran Budaya</strong>: Secara teratur mengorganisir aktivitas pertukaran budaya antara semua ras untuk meningkatkan pemahaman dan rasa hormat timbal balik.</li><li><strong>Area Pemukiman Campuran</strong>: Mendorong pemukiman campuran semua ras, memecah isolasi ras, dan mempromosikan pertukaran sehari-hari.</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Semua ras adalah harta paling berharga di Hengyuanzhou. Keanekaragaman bentuk kehidupan bukanlah akar perpecahan, melainkan kekuatan pendorong evolusi simbiosis. Dengan menetapkan prinsip kesetaraan semua ras, membangun klasifikasi lima silsilah, mempromosikan kerja sama simbiosis antara semua ras, serta mencegah dan menyelesaikan konflik ras, Peradaban Simbiosis Jangkar membebaskan semua ras dari sejarah predasi dan perang, maju bersama menuju era baru evolusi simbiosis.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>51-人族定位与特质 (Posisi dan Karakteristik Ras Manusia)</li><li>52-异族分类与共生 (Klasifikasi dan Simbiosis Ras Asing)</li><li>05-万族共进基本纲领 (Program Dasar Kemajuan Bersama Semua Ras)</li><li>40-共生宪法总纲 (Prinsip Umum Konstitusi Simbiosis)</li></ul>',30)])])}const p=i(r,[["render",t]]);export{o as __pageData,p as default};
